insert into public.exercises(id,name,description,muscle_group,equipment,tracking_type) values('10000000-0000-4000-8000-000000000151','Cable pull-through','Hinge deep with the rope drifting back between your legs, then drive your hips forward to a full standing lockout.','Legs','Cable','weighted'),('10000000-0000-4000-8000-000000000152','Pause squat','Pause two full seconds at the bottom without relaxing, then drive up fast with your chest up.','Legs','Barbell','weighted'),('10000000-0000-4000-8000-000000000153','Deficit deadlift','Stand on a low plate, pull with a flat back from the lower start, and lock out tall.','Back','Barbell','weighted'),('10000000-0000-4000-8000-000000000154','JM press','Lower the bar toward your chin with the elbows tucked, then press back up without flaring.','Arms','Barbell','weighted'),('10000000-0000-4000-8000-000000000155','Walking lunge','Step long, drop the back knee toward the floor, and drive up through the front heel before the next step.','Legs','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000156','Step-up','Drive up through the heel on the box, stand tall without pushing off the trailing leg, and lower with control.','Legs','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000157','Box squat','Sit back to the box, pause without relaxing, and drive up with the knees tracking over your toes.','Legs','Barbell','weighted'),('10000000-0000-4000-8000-000000000158','Toes to bar','Hang without swinging, lift your toes to the bar with straight legs, and lower slowly.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000159','Spider curl','Lie chest-down on an incline bench, curl with strict form, and squeeze at the top.','Arms','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000160','Rope pushdown','Pin the elbows to your sides, split the rope apart at the bottom, and squeeze every lockout.','Arms','Cable','weighted'),('10000000-0000-4000-8000-000000000161','Single-arm dumbbell row','Brace on the bench, pull the dumbbell to your hip without twisting, and lower over three seconds.','Back','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000162','Chest-supported row','Press your chest into the pad, row until the handles reach your ribs, and squeeze your shoulder blades together.','Back','Machine','weighted') on conflict(id) do nothing;